    def fmt(k, s, e):
        return f'{len(s)} {k}\n' + ' '.join(map(str, s)) + '\n' + ' '.join(map(str, e))
    tests = [fmt(1, [1], [1]), fmt(1, [5], [7]), fmt(2, [1, 1], [1, 1]), fmt(3, [1, 1, 10], [100, 100, 1]),
             fmt(2, [5, 3, 8, 2], [4, 9, 2, 7]), fmt(4, [7, 7, 7, 7], [3, 3, 3, 3]),
             fmt(2, [100000, 1, 1], [1, 100000, 100000])]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for _ in range(3):
            k = rng.randint(1, n)
            hs = rng.choice([5, 30, 100000])
            he = rng.choice([5, 30, 100000])
            tests.append(fmt(k, [rng.randint(1, hs) for _ in range(n)], [rng.randint(1, he) for _ in range(n)]))
    N = 100000
    def big(k, hs, he):
        return fmt(k, [rng.randint(1, hs) for _ in range(N)], [rng.randint(1, he) for _ in range(N)])
    tests.append(big(N // 2, 100000, 100000))
    tests.append(big(N, 100000, 100000))
    tests.append(big(1, 100000, 100000))
    tests.append(big(700, 100000, 100000))
    tests.append(fmt(N // 3, [100000] * N, [rng.randint(1, 100000) for _ in range(N)]))
    return tests

